frappe.ui.form.on('User', {
    refresh: function(frm) {
        // Show delete account button for any user account (except system accounts)
        if (frm.doc.name !== 'Administrator' && 
            frm.doc.name !== 'Guest' && 
            !frm.doc.__islocal) {

            // Add primary delete account button
            frm.page.set_primary_action(__('Delete Account'), function() {
                // Create password confirmation dialog
                let d = new frappe.ui.Dialog({
                    title: __('Confirm Account Deletion'),
                    fields: [
                        {
                            fieldtype: 'HTML',
                            options: '<p style="color: red; font-weight: bold;">⚠️ This action cannot be undone. Your account will be permanently disabled.</p>'
                        },
                        {
                            fieldname: 'password',
                            fieldtype: 'Password',
                            label: __('Enter the account password to confirm'),
                            reqd: 1
                        }
                    ],
                    primary_action_label: __('Delete Account'),
                    primary_action: function(values) {
                        if (!values.password) {
                            frappe.msgprint(__('Password is required'));
                            return;
                        }

                        d.hide();

                        // Call server method to delete account
                        frappe.call({
                            method: 'tookio_shop.utils.delete_user_account',
                            args: {
                                user: frm.doc.name,
                                password: values.password
                            },
                            callback: function(r) {
                                if (r.message && r.message.success) {
                                    frappe.msgprint(__('Account deleted successfully. You will be logged out now.'));
                                    // Redirect to login page after short delay
                                    setTimeout(function() {
                                        window.location.href = '/login';
                                    }, 2000);
                                } else {
                                    frappe.msgprint(__('Failed to delete account: ') + (r.message ? r.message.error : 'Unknown error'));
                                }
                            }
                        });
                    }
                });

                d.show();
            }, 'red');
        }
    }
});
